"""Build useful, public editorial pages without changing any configurator code."""
from pathlib import Path
from html import escape as esc
from urllib.parse import urljoin
import json

ROOT = Path(__file__).resolve().parent.parent
BASE = 'https://leroyfactory.fr/'
DATE = '2026-11-14'
PAGES = []
POOL = 'assets/img/view-selection-20261031/coco/01-ambiance-preview.webp'
BATH = 'assets/img/home-refresh-20261031/bathroom-wide-light.webp'
STUDIO = 'shared/lrf-3d/demo/media/randal-studio-one-photoreal-v1-small.webp'
GENERAL = 'shared/lrf-3d/media/public-compositions/lrf-expo-general.webp'
STONE = 'assets/img/saxso-2026/photo-28.jpeg'

def image(src, alt, caption='', eager=False):
    assert (ROOT / src).is_file(), src
    return f'<figure class="reach-figure"><img src="{esc(src)}" alt="{esc(alt)}" width="1200" height="800" loading="{"eager" if eager else "lazy"}" decoding="async">'+(f'<figcaption>{esc(caption)}</figcaption>' if caption else '')+'</figure>'

def links(items):
    return '<div class="reach-links">'+''.join(f'<a href="{esc(u)}">{esc(t)} <span aria-hidden="true">↗</span></a>' for u,t in items)+'</div>'

def section(title, paragraphs, extra=''):
    return f'<section class="seo-section"><h2>{esc(title)}</h2>'+''.join(f'<p>{p}</p>' for p in paragraphs)+extra+'</section>'

def cards(items):
    return '<div class="seo-grid">'+''.join(f'<article class="seo-card"><h3>{esc(t)}</h3><p>{p}</p>{links(l)}</article>' for t,p,l in items)+'</div>'

def tools():
    return section('Des outils visuels pour préparer votre choix',[
        'Comparez les matières dans une pièce, composez le mobilier de salle de bains ou préparez les quantités. Les outils disponibles sont présentés avant leur ouverture ; les espaces professionnels conservent leurs accès habituels.'
    ], '<div class="reach-visual-grid"><article>'+image(STUDIO,'Salle de bains de démonstration du configurateur RANDAL Studio One','Rendu du configurateur · projet de démonstration')+'<h3>Composer une salle de bains en 3D</h3><p>Mobilier, vasques, miroirs et revêtements : préparez une composition et échangez sur des choix précis.</p>'+links([('configurateur-salle-de-bain-3d.html','Découvrir les ateliers 3D')])+'</article><article>'+image(POOL,'Ambiance fabricant VIEW COCO pour comparer un carrelage de terrasse','Ambiance fabricant · VIEW COCO')+'<h3>Visualiser le carrelage et préparer la pose</h3><p>Découvrez les outils de visualisation, de calepinage et de calcul des joints, plots et croisillons.</p>'+links([('configurateurs.html','Voir les configurateurs'),('logiciel-calepinage-carrelage.html','Préparer le calepinage')])+'</article></div>')

def profiles():
    return section('Un parcours adapté à votre projet',[],cards([
        ('Particuliers','Préparez une rénovation ou une construction : photos, dimensions, références et échantillons pour échanger avec un revendeur.',[('carrelage-particuliers.html','Préparer mon projet')]),
        ('Professionnels du carrelage','Négoces, showrooms et artisans : présentez les collections, préparez une sélection et retrouvez les accès professionnels.',[('carrelage-professionnels.html','Accompagnement professionnel')]),
        ('Architectes et décorateurs','Travaillez les associations de matières, préparez les détails d’un projet et transmettez une sélection lisible au professionnel chargé de la fourniture.',[('carrelage-architectes.html','Préparer une prescription')])]))

def page(file, title, heading, description, lead, body, hero=POOL, label='Carrelage & salle de bains', parent=None, area=None, category='editorial'):
    url = BASE + file
    crumb = [{'@type':'ListItem','position':1,'name':'Accueil','item':BASE}]
    if parent: crumb.append({'@type':'ListItem','position':2,'name':parent[1],'item':BASE+parent[0]})
    crumb.append({'@type':'ListItem','position':len(crumb)+1,'name':heading,'item':url})
    graph = [
        {'@type':'WebPage','@id':url+'#webpage','url':url,'name':heading,'description':description,'inLanguage':'fr-FR','dateModified':DATE,'isPartOf':{'@id':BASE+'#website'},'about':{'@id':BASE+'#organization'},'primaryImageOfPage':{'@type':'ImageObject','url':BASE+hero},'breadcrumb':{'@id':url+'#breadcrumb'}},
        {'@type':'BreadcrumbList','@id':url+'#breadcrumb','itemListElement':crumb}
    ]
    if area:
        graph.append({'@type':'Service','@id':url+'#accompagnement','name':'Conseil et sélection carrelage et salle de bains — '+area,'serviceType':'Conseil, sélection de collections et mise en relation professionnelle','provider':{'@id':BASE+'#organization'},'areaServed':{'@type':'Place','name':area},'url':url})
    ld = json.dumps({'@context':'https://schema.org','@graph':graph},ensure_ascii=False).replace('</','<\\/')
    parent_crumb=f' / <a href="{parent[0]}">{esc(parent[1])}</a>' if parent else ''
    source=f'''<!doctype html>
<html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#f6f3ed">
<title>{esc(title)}</title><meta name="description" content="{esc(description)}"><meta name="robots" content="index,follow,max-image-preview:large,max-snippet:-1"><link rel="canonical" href="{url}"><link rel="icon" href="assets/img/logo03lrf.png">
<meta property="og:type" content="website"><meta property="og:locale" content="fr_FR"><meta property="og:site_name" content="LE ROY FACTORY"><meta property="og:title" content="{esc(title)}"><meta property="og:description" content="{esc(description)}"><meta property="og:url" content="{url}"><meta property="og:image" content="{BASE+hero}"><meta name="twitter:card" content="summary_large_image">
<link rel="stylesheet" href="assets/css/seo-editorial.css?v=20261107-logo-rond1"><link rel="stylesheet" href="assets/css/seo-reach.css?v=20261114-1"><script type="application/ld+json">{ld}</script></head>
<body class="seo-page reach-page"><a class="skip-link" href="#contenu">Aller au contenu</a><header class="seo-header"><div class="seo-shell seo-header-inner"><a class="seo-brand" href="index.html" aria-label="LE ROY FACTORY — accueil"><img src="assets/img/logo03lrf.png" alt="LE ROY FACTORY" width="72" height="72"></a><nav class="seo-nav" aria-label="Navigation principale"><a href="univers.html">Collections</a><a href="fabricants-carrelage-salle-de-bain.html">Fabricants</a><a href="configurateurs.html">Configurateurs</a><a href="carrelage-paca-occitanie-corse.html">Nos secteurs</a><a href="contact.html">Contact</a></nav></div></header>
<main id="contenu" class="seo-shell"><nav class="seo-breadcrumb" aria-label="Fil d’Ariane"><a href="index.html">Accueil</a>{parent_crumb} / {esc(heading)}</nav><section class="seo-hero reach-hero"><div><p class="seo-eyebrow">{esc(label)}</p><h1>{esc(heading)}</h1><p class="seo-lead">{lead}</p><div class="seo-actions"><a class="seo-button" href="contact.html">Parler de mon projet</a><a class="seo-button secondary" href="univers.html">Explorer les collections</a></div></div>{image(hero,'Ambiance de carrelage et salle de bains présentée par LE ROY FACTORY','Visuel de collection ou projet de démonstration · à confirmer par échantillon',True)}</section>
{body}
<section class="seo-section reach-contact"><p class="seo-eyebrow">Une sélection à concrétiser</p><h2>Partons de votre pièce et de vos usages.</h2><p>Indiquez votre commune, votre activité, les surfaces concernées et les références qui vous intéressent. LE ROY FACTORY est une agence commerciale : l’équipe vous conseille et précise le circuit de fourniture ou le revendeur adapté au projet.</p><div class="seo-actions"><a class="seo-button" href="contact.html">Contacter Jérôme ou Coryne</a><a class="seo-button secondary" href="realisations.html">Voir les réalisations</a></div></section><p class="seo-meta">Présentation mise à jour le 14 novembre 2026. Les produits, formats, finitions, conditions et possibilités d’accompagnement sont confirmés selon le fabricant et le projet.</p></main>
<footer class="seo-footer"><div class="seo-shell"><nav aria-label="Pour poursuivre"><a href="carrelage-paca-occitanie-corse.html">PACA, Occitanie & Corse</a><a href="carrelage-particuliers.html">Particuliers</a><a href="carrelage-professionnels.html">Professionnels</a><a href="carrelage-architectes.html">Architectes</a><a href="catalogues.html">Catalogues</a><a href="configurateurs.html">Configurateurs</a><a href="mentions-legales.html">Mentions légales</a></nav><p>© 2026 LE ROY FACTORY · Agence commerciale carrelage & salle de bains</p></div></footer></body></html>'''
    (ROOT/file).write_text(source)
    PAGES.append({'file':file,'updated':DATE,'category':category,'title':title,'images':[BASE+hero]})

