    if brand=='REVIGLASS': body+=section('Collections à découvrir',[],links([('reviglass-midas.html','Collection MIDAS'),('reviglass-s-tones.html','Collection S-TONES')]))
    body+=profiles()
    page(file,heading+' | LRF',heading,f'{heading} : visuels, catalogue et conseils pour préparer une sélection avec LE ROY FACTORY en PACA, Occitanie et Corse.',intro,body,hero=hero,label=brand+' · Collections & sélection',parent=('fabricants-carrelage-salle-de-bain.html','Fabricants'),category='brand')

